// Shapes from the services' OpenAPI (src/api/types, generated by `npm run api:types`).

import type { components } from './types/auth'
import type { components as OpsComponents } from './types/operations'

type Auth = components['schemas']

export type Me = Auth['Me']
export type TokenResponse = Auth['TokenResponse']
export type UserOut = Auth['UserOut']
export type UserPage = Auth['UserPage']
export type OrgOut = Auth['OrgOut']
export type OrgPage = Auth['OrgPage']
export type RegisterIn = Auth['RegisterIn']
export type MePatch = Auth['MePatch']
export type InviteIn = Auth['InviteIn']
export type ApproveIn = Auth['ApproveIn']
export type RejectIn = Auth['RejectIn']
export type OrgIn = Auth['OrgIn']
export type MaterialTheme = Auth['MaterialTheme']
export type BrandingIn = Auth['BrandingIn']
export type BrandingOut = Auth['BrandingOut']

export type Role = 'client' | 'technician' | 'admin' | 'viewer'
export type UserStatus = 'pending' | 'invited' | 'active' | 'disabled' | 'rejected'

// The operations service (openapi/operations.json)
type Ops = OpsComponents['schemas']

export type StationSummary = Ops['StationSummary']
export type StationPage = Ops['StationPage']
export type StationDetail = Ops['StationDetail']
export type StationFacets = Ops['StationFacets']
export type InstalledUnit = Ops['InstalledUnit']
export type SensorUnitDetail = Ops['SensorUnitDetail']
export type CalibrationOut = Ops['CalibrationOut']
export type CalibrationPage = Ops['CalibrationPage']
export type DueList = Ops['DueList']
export type DueUnit = Ops['DueUnit']

export type StationStatus = 'operational' | 'degraded' | 'offline' | 'decommissioned'
